class SingleFlight:
    def __init__(self, loader):
        self._loader = loader
        self._inflight = {}  # key -> {"task": Task, "waiters": set[Future]}
        self._closed = False

    async def get(self, key):
        if self._closed:
            raise RuntimeError("SingleFlight is closed")
        entry = self._inflight.get(key)
        if entry is None:
            task = asyncio.create_task(self._loader(key))
            entry = {"task": task, "waiters": set()}
            self._inflight[key] = entry

            def _on_done(t, _key=key):
                # Cleanup race guard: remove the entry only if it still
                # refers to THIS task (a newer task may have replaced it).
                cur = self._inflight.get(_key)
                if cur is not None and cur["task"] is t:
                    del self._inflight[_key]
                # Retrieve the exception so it is never "never retrieved",
                # even if every waiter cancelled and nobody awaits it.
                if not t.cancelled():
                    t.exception()
            task.add_done_callback(_on_done)
        else:
            task = entry["task"]

        if task.done():
            # Task already finished (e.g. interleaving); propagate result.
            return task.result()

        loop = asyncio.get_running_loop()
        fut = loop.create_future()
        entry["waiters"].add(fut)

        def _relay(t):
            if fut.done():
                return
            if t.cancelled():
                fut.cancel()
            else:
                exc = t.exception()
                if exc is not None:
                    fut.set_exception(exc)
                else:
                    fut.set_result(t.result())
        task.add_done_callback(_relay)

        try:
            return await fut
        except asyncio.CancelledError:
            # This waiter was cancelled: detach only itself. The loader
            # task keeps running for remaining waiters (or alone).
            entry["waiters"].discard(fut)
            task.remove_done_callback(_relay)
            if not entry["waiters"] and not task.done():
                # Last waiter gone: nobody will await the result, but the
                # task must run to completion and its exception must still
                # be retrieved. _on_done already does the retrieval; keep
                # it attached and let the task finish in the background.
                pass
            raise

    async def close(self):
        self._closed = True
        tasks = [e["task"] for e in self._inflight.values() if not e["task"].done()]
        for t in tasks:
            t.cancel()
        if tasks:
            # Await them; return_exceptions ensures we also retrieve their
            # (CancelledError or loader) exceptions without raising.
            await asyncio.gather(*tasks, return_exceptions=True)
        self._inflight.clear()
", "explanation": "Each in-flight key maps to its loader Task plus a set of per-waiter Futures. Waiters await their own Future, so cancelling one waiter only cancels that Future; the loader Task is never cancelled by a waiter. On cancellation the waiter detaches its Future and its relay callback; if it was the last waiter, the task is left running to completion in the background. Exception retrieval: the task's done callback (_on_done) always calls t.exception() (unless the task itself was cancelled), so even when every waiter cancels and nobody awaits, the exception is consumed and no 'Task exception was never retrieved' warning occurs; close() additionally gathers outstanding tasks with return_exceptions=True, which retrieves exceptions of tasks it cancels. Cleanup race: the entry is deleted in _on_done only if self._inflight[key] still is the same task object ('remove completed entries only if they still refer to that task'), so a stale done callback from an old task can never delete a newer entry. Timeline check: A and B join the first load; A's cancellation detaches only A (loader_cancelled_by_a=False); the loader returns 17, B's Future gets 17 (b_value=17), _on_done removes the entry and retrieves the result; C then starts a fresh load returning 18 (c_value=18, loader_calls=2); close() finds no outstanding tasks and completes; A's await raised CancelledError (a_cancelled=True). Limitations: assumes a single event loop and cooperative (non-blocking) loaders; get() after close() raises; results are not cached after completion."}

